import unittest
from src.quantity import validate_quantity


class QuantityContract(unittest.TestCase):
    def test_zero_is_valid(self):
        self.assertEqual(validate_quantity(0), 0)

    def test_positive_is_valid(self):
        self.assertEqual(validate_quantity(3), 3)

    def test_negative_is_rejected(self):
        with self.assertRaises(ValueError):
            validate_quantity(-1)


class AggregationContract(unittest.TestCase):
    def test_empty_is_zero(self):
        from src.quantity import total_quantity
        self.assertEqual(total_quantity([]), 0)

    def test_sum_of_valid_quantities(self):
        from src.quantity import total_quantity
        self.assertEqual(total_quantity([2, 3]), 5)

    def test_aggregation_rejects_negative_quantity(self):
        from src.quantity import total_quantity
        with self.assertRaises(ValueError):
            total_quantity([2, -1])
